/** Settle any still-running descendants before the root handle is disposed. */
async function drainDescendants(ctx: Context, agent: Agent): Promise<void> {
  try {
    await subagentLifecycle(ctx)?.drainDescendants([agent])
  } catch (error: unknown) {
